// Increase scale
s += s;
}
// March forward
s = 0.01 + abs(p.y);
d += s;
// Accumulate color with cosine gradient
o += (1.0 + audioHighSmooth / 3.0 + cos(d + vec3(4.0, 2.0, 1.0))) / s;
}
// Final color processing
o = tanh(o / 6.0e3);
ret = vec4(o, 1.0);
}

